from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
d = ImageDraw.Draw(im)
for x in range(450, 1450, 50):
    col = (255,80,80) if x%100==0 else (100,150,255)
    d.line([(x,400),(x,900)], fill=col, width=2 if x%100==0 else 1)
    if x%100==0: d.text((x+2,402), str(x), fill=(255,255,0))
for y in range(450, 900, 50):
    col = (255,80,80) if y%100==0 else (100,150,255)
    d.line([(450,y),(1450,y)], fill=col, width=2 if y%100==0 else 1)
    if y%100==0: d.text((452,y+2), str(y), fill=(255,255,0))
im.crop((450,400,1450,900)).resize((2000,1000), Image.LANCZOS).save('grid_lr2.png')
print('ok')
